fn reverse_string(s: &Vec<char>) -> Vec<char> {
    let len = s.len();
    let mut result = Vec::with_capacity(len);

    for i in 0..len {
        // Append element from the end of s
        result.push(s[len - 1 - i]);
    }

    result
}